action.mutation:
mutation UpdateWorkcenterIotTag($payload: [WorkcenterIotTagUpdatePayloadInput!]!) {
  mutation: updateWorkcenterIotTag(payload: $payload) { 
    id
    label
  }
}

action.query:
query (
  $iotTagTypeId: String!
  $iotTagUseCaseId: String!
){
  iotTagType(
    where:{
      id:{_eq: $iotTagTypeId}
    }
  ){
    edges{
      node{ configurationSchema}
    }
  }

  iotTagUseCase(
    where:{
      id:{_eq: $iotTagUseCaseId}
    }
  ){
    edges{
      node{ configurationSchema}
    }
  }
}

action.mutation:
mutation CreateIotTag($payload: [IotTagCreatePayloadInput!]!) {
  mutation: createIotTag(payload: $payload) { 
    id
    name
  }
}
